export const PURESOC_LEGAL_CAVEAT =
  "This assessment is generated by PureSOC/SiSoN based on configured regulatory sources, customer-provided answers, and connected provider telemetry. It is an internal readiness and evidence-support tool, not a legal opinion, certification, or substitute for advice from the relevant national competent authority, legal counsel, auditor, or cybersecurity assessor.";

export const supportedLocales = ["en", "ro"] as const;

export type PureSocLocale = (typeof supportedLocales)[number];

export const defaultLocale: PureSocLocale = "en";

export const LEGAL_CAVEAT_MESSAGE_KEY = "puresoc.legal_caveat.internal_readiness.v1";

export interface LocaleResolution {
  fallbackUsed: boolean;
  locale: PureSocLocale;
  requestedLocale?: string;
}

export interface LocalizedMessageResolution {
  fallbackUsed: boolean;
  messageKey: typeof LEGAL_CAVEAT_MESSAGE_KEY;
  normalizedLocale: PureSocLocale;
  requestedLocale?: string;
  resolvedLocale: PureSocLocale;
  text: string;
}

export const isPureSocLocale = (value: string): value is PureSocLocale =>
  (supportedLocales as readonly string[]).includes(value);

export const resolvePureSocLocale = (locale?: string | null): LocaleResolution => {
  const requestedLocale = locale?.trim() || undefined;
  const normalized = requestedLocale?.toLowerCase().replace("_", "-").split("-")[0];

  if (normalized && isPureSocLocale(normalized)) {
    return {
      fallbackUsed: false,
      locale: normalized,
      requestedLocale
    };
  }

  return {
    fallbackUsed: requestedLocale !== undefined,
    locale: defaultLocale,
    requestedLocale
  };
};

const legalCaveatMessages: Partial<Record<PureSocLocale, string>> = {
  en: PURESOC_LEGAL_CAVEAT
};

export const resolveLegalCaveatMessage = (locale?: string | null): LocalizedMessageResolution => {
  const localeResolution = resolvePureSocLocale(locale);
  const localizedText = legalCaveatMessages[localeResolution.locale];
  const resolvedLocale = localizedText ? localeResolution.locale : defaultLocale;

  return {
    fallbackUsed: localeResolution.fallbackUsed || resolvedLocale !== localeResolution.locale,
    messageKey: LEGAL_CAVEAT_MESSAGE_KEY,
    normalizedLocale: localeResolution.locale,
    requestedLocale: localeResolution.requestedLocale,
    resolvedLocale,
    text: localizedText ?? legalCaveatMessages[defaultLocale] ?? PURESOC_LEGAL_CAVEAT
  };
};

export const findingSeverities = ["informational", "low", "medium", "high", "critical"] as const;

export type FindingSeverity = (typeof findingSeverities)[number];

export const actionableSeverities = ["low", "medium", "high", "critical"] as const;

export type ActionableSeverity = (typeof actionableSeverities)[number];

export const isActionableSeverity = (severity: FindingSeverity | string): severity is ActionableSeverity =>
  (actionableSeverities as readonly string[]).includes(severity);

export type Confidence = "low" | "medium" | "high";

export interface SourceReference {
  sourceRecordId: string;
  article?: string;
  paragraph?: string;
  annex?: string;
  nationalReference?: string;
  sourceUrl?: string;
  sourceVersion?: string;
  label?: string;
}

export type ProviderFindingForComplianceStatus = "open" | "acknowledged" | "resolved" | "suppressed";

export interface ProviderFindingForCompliance {
  id: string;
  providerKey: string;
  moduleKey: string;
  findingKey: string;
  title: string;
  summary: string;
  severity: FindingSeverity;
  status: ProviderFindingForComplianceStatus;
  evidence: Record<string, unknown>;
}

export type RecommendationActionType =
  | "manual"
  | "guided"
  | "technical"
  | "process"
  | "evidence_upload"
  | "country_registration"
  | "incident_reporting";

export type RecommendationAutomationMode = "manual" | "guided" | "preflightable" | "executable_later";

export type RecommendationStatus = "proposed" | "accepted" | "planned" | "completed" | "dismissed";

export interface RecommendationSummary {
  id: string;
  organizationId?: string;
  sourceFindingId?: string;
  sourceFindingIds?: readonly string[];
  manualTaskIds?: readonly string[];
  controlId: string;
  jurisdiction: string;
  title: string;
  summary: string;
  severity?: ActionableSeverity;
  confidence?: Confidence;
  recommendationType: RecommendationActionType;
  automationMode: RecommendationAutomationMode;
  requiredPermissions: readonly string[];
  requiredLicense: readonly string[];
  expectedChange?: string;
  blastRadius?: string;
  manualFallback?: string;
  evidenceRequired: boolean;
  status: RecommendationStatus;
  sourceReferences?: readonly SourceReference[];
}

